#include <map>
#include <array>
#include <vector>
// Native complete finite frontier analysis. No Python dispatch or research calculation.
#include <nlohmann/json.hpp>
#include <openssl/sha.h>
#include <fstream>
#include <sstream>
#include <iostream>
#include <iomanip>
#include <filesystem>
using J=nlohmann::ordered_json;namespace fs=std::filesystem;
void need(bool b,const char*s){if(!b)throw std::runtime_error(s);}
std::string read(const fs::path&p){std::ifstream f(p,std::ios::binary);need(bool(f),"input");return{std::istreambuf_iterator<char>(f),{}};}
std::string hash(const std::string&s){unsigned char d[32];SHA256((const unsigned char*)s.data(),s.size(),d);std::ostringstream o;for(auto c:d)o<<std::hex<<std::setw(2)<<std::setfill('0')<<int(c);return o.str();}
bool alg(const J&p){for(const auto&w:p["works"])if(w["result"]["kind"]!=1)return false;return true;}
int main(int argc,char**argv){try{need(argc==4,"analysis root head output; three math JSONs on stdin");fs::path root=argv[1];std::string head=argv[2];J docs[3];for(auto&d:docs)std::cin>>d;need(docs[0]["schema"]=="twist.first-row.audit/v1"&&docs[1]["schema"]=="twist.setup-rank.audit/v1"&&docs[2]["schema"]=="twist.two-base.audit/v1"&&docs[2]["head"]==head,"math input scopes/source");
std::map<std::array<int,3>,J>math;for(int m=0;m<3;m++)for(const auto&p:docs[m]["profiles_data"]){need(p["cap"]==(m==2?2:3),"actual certificate cap");need(math.emplace(std::array<int,3>{m,p["route"],p["policy"]},p).second,"duplicate math cell");}need(math.size()==3045,"both B3 methods/all455 and B2/all105 in allthree roles");
std::map<std::array<int,4>,unsigned long long>cost;std::map<std::array<int,2>,unsigned long long>aa;J sources=J::array();unsigned long long sums[2]={0,0};
for(int stream=0;stream<2;stream++)for(int index=0;index<38;index++){std::ostringstream name;name<<"audit-"<<(stream==0?'A':'B')<<'-'<<std::setw(2)<<std::setfill('0')<<index<<".json";auto bytes=read(root/name.str());J doc=J::parse(bytes);int first=index*12,end=std::min(first+12,455),b2=std::max(0,std::min(end,105)-first);need(doc["schema"]=="twist.policy-counter-audit.two-base.v1"&&doc["head"]==head&&doc["stream"]==(stream==0?"A":"B")&&doc["first_policy"]==first&&doc["end_policy"]==end,"source/order/case binding");need(doc["intervals"]==6*(end-first)+3*b2+3&&doc["warmup_workloads"]==(first<105?540:360)&&doc["positive_detected"]==true&&doc["negative_within_tolerance"]==true,"all intervals and real calibration required");aa[{stream,index}]=std::max(1000ULL,doc["aa_instruction_difference"].get<unsigned long long>());sources.push_back(J{{"path",name.str()},{"sha256",hash(bytes)}});
for(const auto&r:doc["records"]){need(r["original_scalars_checked"]==30,"every separate target check");if(r["label"]!="plain")continue;int m=r["method"],route=r["route"],p=r["policy"];need(m>=0&&m<3&&route>=3&&route<6&&p>=first&&p<end&&(m<2||p<105),"case membership");auto ir=r["instruction_reads"].get<unsigned long long>();need(ir>0&&cost.emplace(std::array<int,4>{stream,m,route,p},ir).second,"unique positive measured body");sums[stream]+=ir;}}
need(cost.size()==6090,"every B3/B2 method/role/policy in BOTH streams");auto lo=[&](int m,int r,int p){return std::min(cost.at({0,m,r,p}),cost.at({1,m,r,p}));};auto hi=[&](int m,int r,int p){return std::max(cost.at({0,m,r,p}),cost.at({1,m,r,p}));};auto margin=[&](int p){return std::max(aa.at({0,p/12}),aa.at({1,p/12}));};
J frontier=J::array();for(bool include_b2:{false,true})for(bool require_alg:{false,true}){unsigned long long best=~0ULL;int eligible=0,bm=-1,br=-1,bp=-1;for(int m=0;m<(include_b2?3:2);m++)for(int r:{3,5})for(int p=0;p<(m==2?105:455);p++){if(require_alg&&!alg(math.at({m,r,p})))continue;eligible++;auto value=lo(m,r,p);if(value<best){best=value;bm=m;br=r;bp=p;}}need(eligible>0,"never compare to empty source frontier");int lower=0,above=0,overlap=0,cn=0;J candidates=J::array();for(int p=0;p<105;p++){if(require_alg&&!alg(math.at({2,4,p})))continue;cn++;auto low=lo(2,4,p),high=hi(2,4,p),t=margin(p);bool wins=high+t<best;lower+=wins;above+=low>best+t;overlap+=!wins&&!(low>best+t);candidates.push_back(J{{"policy",p},{"min_Ir",low},{"max_Ir",high},{"margin",t},{"below_source_lower_envelope",wins},{"source_lower_over_candidate_upper_ratio",double(best)/double(high)}});}frontier.push_back(J{{"source_includes_new_B2",include_b2},{"all30_algebraic",require_alg},{"eligible_source_profiles",eligible},{"source_lower_Ir",best},{"source_method",bm},{"source_role",br},{"source_policy",bp},{"candidate_profiles",cn},{"candidate_below_source",lower},{"candidate_above_source",above},{"candidate_overlap",overlap},{"candidates",candidates}});}
J data=J::array();for(int m=0;m<3;m++)for(int r=3;r<6;r++)for(int p=0;p<(m==2?105:455);p++){const auto&profile=math.at({m,r,p});int algn=0,identity=0,blocked=0;for(const auto&w:profile["works"]){int k=w["result"]["kind"];algn+=k==1;identity+=k==2;blocked+=k==0;}data.push_back(J{{"method",m},{"role",r},{"policy",p},{"base_size",m==2?2:3},{"membership_witness_cap",m==2?2:3},{"min_Ir",lo(m,r,p)},{"max_Ir",hi(m,r,p)},{"calibration_margin",margin(p)},{"algebraic",algn},{"identity",identity},{"blocked",blocked},{"initial_rank_numerator",profile["rank_numerator"]}});}
J result={{"schema","twist.two-base-full-description/v1"},{"head",head},{"source_receipts",sources},{"main_intervals",6090},{"primary_cold_calls_both_streams",182700},{"actual_nonidentity_source_points",30},{"main_Ir_by_stream",J::array({sums[0],sums[1]})},{"full_source_frontier",frontier},{"all_profiles",data},{"degree_scope","Membership univariate f/h/root-cover cap2 vs3; field scalar exponent/sqrt not bounded by polynomial degree; originalS3 pullback/intrinsic regularity unknown"},{"wall_speed_claim",false},{"signed_verdict",false}};need(!fs::exists(argv[3]),"fresh analysis only");std::ofstream f(argv[3]);f<<result.dump()<<'\n';need(bool(f),"analysis write");return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 101;}}
